class Solution:
    def countGoodIntegers(self, l, r, directions):
        path = [(0, 0)]
        row = col = 0
        for ch in directions:
            if ch == 'D': row += 1
            else: col += 1
            path.append((row, col))
        def good(x):
            ds = str(x).zfill(16)
            last = -1
            for rr, cc in path:
                d = int(ds[rr * 4 + cc])
                if last >= 0 and d < last: return False
                last = d
            return True
        return sum(1 for x in range(l, r + 1) if good(x))

