class Solution {
public:
    long long countGoodIntegers(long long l, long long r, string directions) {
        vector<pair<int,int>> path = {{0, 0}};
        int row = 0, col = 0;
        for (char c : directions) {
            if (c == 'D') row++; else col++;
            path.push_back({row, col});
        }
        auto good = [&](long long x) {
            string ds = to_string(x);
            ds = string(16 - ds.size(), '0') + ds;
            int last = -1;
            for (auto& [rr, cc] : path) {
                int d = ds[rr * 4 + cc] - '0';
                if (last >= 0 && d < last) return false;
                last = d;
            }
            return true;
        };
        long long ans = 0;
        for (long long x = l; x <= r; x++) if (good(x)) ans++;
        return ans;
    }
};

