    public long countGoodIntegers(long l, long r, String directions) {
        int[][] path = new int[7][2]; path[0] = new int[]{0, 0};
        int row = 0, col = 0;
        for (int t = 0; t < 6; t++) {
            if (directions.charAt(t) == 'D') row++; else col++;
            path[t + 1] = new int[]{row, col};
        }
        long ans = 0;
        for (long x = l; x <= r; x++) {
            String ds = String.format("%016d", x);
            int last = -1; boolean ok = true;
            for (int[] p : path) {
                int d = ds.charAt(p[0] * 4 + p[1]) - '0';
                if (last >= 0 && d < last) { ok = false; break; }
                last = d;
            }
            if (ok) ans++;
        }
        return ans;
    }
}

