from functools import lru_cache
class Solution:
    def countGoodIntegers(self, l, r, directions):
        idx = [0]
        row = col = 0
        for ch in directions:
            if ch == 'D': row += 1
            else: col += 1
            idx.append(row * 4 + col)
        onpath = [False] * 16
        for p in idx: onpath[p] = True
        def count(limit):
            ds = str(limit).zfill(16)
            @lru_cache(None)
            def dp(p, tight, last):
                if p == 16: return 1
                hi = int(ds[p]) if tight else 9
                tot = 0
                for d in range(hi + 1):
                    if onpath[p] and last >= 0 and d < last: continue
                    tot += dp(p + 1, tight and d == hi, d if onpath[p] else last)
                return tot
            return dp(0, True, -1)
        return count(r) - count(l - 1)

