class Solution {
public:
    long long countGoodIntegers(long long l, long long r, string directions) {
        bool onpath[16] = {}; onpath[0] = true;
        int row = 0, col = 0;
        for (char c : directions) {
            if (c == 'D') row++; else col++;
            onpath[row * 4 + col] = true;
        }
        auto count = [&](long long limit) {
            string ds = to_string(limit);
            ds = string(16 - ds.size(), '0') + ds;
            long long memo[17][2][11];
            memset(memo, -1, sizeof(memo));
            function<long long(int,int,int)> dp = [&](int p, int tight, int last) -> long long {
                if (p == 16) return 1;
                long long& res = memo[p][tight][last + 1];
                if (res >= 0) return res;
                int hi = tight ? ds[p] - '0' : 9;
                long long tot = 0;
                for (int d = 0; d <= hi; d++) {
                    if (onpath[p] && last >= 0 && d < last) continue;
                    tot += dp(p + 1, tight && d == hi, onpath[p] ? d : last);
                }
                return res = tot;
            };
            return dp(0, 1, -1);
        };
        return count(r) - count(l - 1);
    }
};

