class Solution {
    public long countGoodIntegers(long l, long r, String directions) {
        boolean[] onpath = new boolean[16]; onpath[0] = true;
        int row = 0, col = 0;
        for (char c : directions.toCharArray()) {
            if (c == 'D') row++; else col++;
            onpath[row * 4 + col] = true;
        }
        return count(r, onpath) - count(l - 1, onpath);
    }
    private long count(long limit, boolean[] onpath) {
        String s = Long.toString(limit);
        StringBuilder sb = new StringBuilder();
        for (int i = s.length(); i < 16; i++) sb.append('0');
        sb.append(s);
        String ds = sb.toString();
        Long[][][] memo = new Long[17][2][11];
        return dp(0, 1, -1, ds, onpath, memo);
    }
    private long dp(int p, int tight, int last, String ds, boolean[] onpath, Long[][][] memo) {
        if (p == 16) return 1;
        if (memo[p][tight][last + 1] != null) return memo[p][tight][last + 1];
        int hi = tight == 1 ? ds.charAt(p) - '0' : 9;
        long tot = 0;
        for (int d = 0; d <= hi; d++) {
            if (onpath[p] && last >= 0 && d < last) continue;
            tot += dp(p + 1, (tight == 1 && d == hi) ? 1 : 0, onpath[p] ? d : last, ds, onpath, memo);
        }
        memo[p][tight][last + 1] = tot;
        return tot;
    }
}

