var countGoodIntegers = function(l, r, directions) {
    const onpath = new Array(16).fill(false); onpath[0] = true;
    let row = 0, col = 0;
    for (const c of directions) {
        if (c === 'D') row++; else col++;
        onpath[row * 4 + col] = true;
    }
    function count(limit) {
        let ds = String(limit);
        while (ds.length < 16) ds = '0' + ds;
        const memo = new Map();
        function dp(p, tight, last) {
            if (p === 16) return 1n;
            const key = p * 32 + (last + 1) * 2 + tight;
            if (memo.has(key)) return memo.get(key);
            const hi = tight ? +ds[p] : 9;
            let tot = 0n;
            for (let d = 0; d <= hi; d++) {
                if (onpath[p] && last >= 0 && d < last) continue;
                tot += dp(p + 1, tight && d === hi ? 1 : 0, onpath[p] ? d : last);
            }
            memo.set(key, tot);
            return tot;
        }
        return dp(0, 1, -1);
    }
    return Number(count(r) - count(l - 1));
};
